/**
 * Bounded Asynchronous Task Queue with Backpressure, Cancellation, and Graceful Shutdown
 * 
 * Features:
 * - Bounded capacity with backpressure (enqueue blocks when full)
 * - Task cancellation via AbortSignal
 * - Graceful shutdown (drain pending tasks, reject new ones)
 * - Typed errors for all failure modes
 * - Deterministic behavior for testing
 */

// ============================================================================
// Types and Interfaces
// ============================================================================

export type Task<T> = () => Promise<T>;

export interface TaskOptions {
  /** Optional abort signal for cancellation */
  signal?: AbortSignal;
  /** Optional priority (lower number = higher priority, default 0) */
  priority?: number;
  /** Optional timeout in milliseconds */
  timeout?: number;
}

export interface QueueStats {
  /** Number of tasks currently executing */
  active: number;
  /** Number of tasks waiting in the queue */
  pending: number;
  /** Total number of tasks that have completed (successfully or with error) */
  completed: number;
  /** Total number of tasks that have been cancelled */
  cancelled: number;
  /** Total number of tasks that have failed */
  failed: number;
  /** Maximum capacity of the queue */
  capacity: number;
  /** Whether the queue is shutting down */
  isShuttingDown: boolean;
  /** Whether the queue is closed */
  isClosed: boolean;
}

export interface EnqueueResult<T> {
  /** Promise that resolves with the task result or rejects with an error */
  promise: Promise<T>;
  /** Unique identifier for the task */
  id: string;
}

// ============================================================================
// Error Classes
// ============================================================================

export class QueueError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'QueueError';
  }
}

export class QueueFullError extends QueueError {
  constructor(message = 'Queue is full') {
    super(message);
    this.name = 'QueueFullError';
  }
}

export class QueueClosedError extends QueueError {
  constructor(message = 'Queue is closed') {
    super(message);
    this.name = 'QueueClosedError';
  }
}

export class TaskCancelledError extends QueueError {
  constructor(message = 'Task was cancelled') {
    super(message);
    this.name = 'TaskCancelledError';
  }
}

export class TaskTimeoutError extends QueueError {
  constructor(message = 'Task timed out') {
    super(message);
    this.name = 'TaskTimeoutError';
  }
}

export class TaskExecutionError extends QueueError {
  public readonly cause: unknown;

  constructor(message: string, cause?: unknown) {
    super(message);
    this.name = 'TaskExecutionError';
    this.cause = cause;
  }
}

