  id: string;
  task: Task<T>;
  options: TaskOptions;
  resolve: (value: T) => void;
  reject: (reason: unknown) => void;
  promise: Promise<T>;
  status: 'pending' | 'running' | 'completed' | 'cancelled' | 'failed';
  createdAt: number;
  startedAt?: number;
  completedAt?: number;
  abortController?: AbortController;
  timeoutId?: ReturnType<typeof setTimeout>;
}

